-- New Leaf Hearing Care: add the Signia Pure Charge&Go MaX section (insert only) to /signia-hearing-aids/
-- Applies only if the stored page is still exactly what was reviewed.
UPDATE ec_hearing_aids SET content='[{"_type":"block","_key":"k33m","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k33l","text":"Signia Hearing Aids Available In Colorado","marks":[]}]},{"_type":"block","_key":"sgm000","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"sgm001","text":"Signia Pure Charge&Go MaX","marks":[]}]},{"_type":"block","_key":"sgm002","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"sgm003","text":"Signia MaX (Multi-adaptive Xperience) is Signia''s newest premium hearing aid platform, released in August 2026. It is powered by Acoustic Intelligence™, which runs four Deep Neural Networks at once: Speech Detection, Own Voice Detection, Scene Analysis, and Noise Processing. Together, they help wearers follow group conversations in noisy places without shutting out the rest of the room.","marks":[]}]},{"_type":"block","_key":"sgm004","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"sgm005","text":"The first model on the platform is the Pure Charge&Go MaX, a rechargeable receiver-in-canal (RIC) hearing aid in eight colors. It comes with a pocket-sized portable charger that holds up to four full charges.","marks":[]}]},{"_type":"block","_key":"sgm006","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"sgm007","text":"OneConnect Technology supports Bluetooth® Classic, LE Audio, telecoil, and Auracast™, so it works with nearly any phone or audio system.","marks":[]}]},{"_type":"block","_key":"sgm008","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"sgm009","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"sgm00a","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"sgm00b","text":"RealTime Conversation Enhancement AI: Locates and enhances multiple conversation partners, so users can follow group conversations more easily.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"sgm00c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"sgm00d","text":"Own Voice Processing AI: Recognizes the wearer''s own voice right away for natural sound from the first fitting, with no in-clinic calibration needed.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"sgm00e","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"sgm00f","text":"Dynamic Noise Control AI: Detects what noise is present and where it comes from, then adjusts noise reduction based on whether the wearer is in a conversation.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"nls001","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"nls002","text":"Signia Active Mini IX","marks":[]}]},{"_type":"block","_key":"nls003","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nls004","text":"Signia Active Mini IX combines modern style with advanced hearing technology in a compact, earbud-inspired design. It is created for people who want hearing support that blends naturally into everyday life.","marks":[]}]},{"_type":"block","_key":"nls005","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nls006","text":"The Active Mini IX offers clear sound, wireless connectivity, and all-day comfort in a sleek and portable package.","marks":[]}]},{"_type":"block","_key":"nls007","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nls008","text":"It comes with a rechargeable design and Bluetooth streaming features that make it easy to enjoy calls, music, podcasts, and TV audio directly from compatible devices.","marks":[]}]},{"_type":"block","_key":"nls009","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nls010","text":"Signia Active Mini IX delivers a balance of style, convenience, and hearing performance in one discreet solution - perfect for active and social lifestyles.","marks":[]}]},{"_type":"block","_key":"nls011","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nls012","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"nls013","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nls014","text":"Integrated Xperience (IX) platform: Enhances speech understanding and keeps conversations clear in noisy environments.","marks":[]}]},{"_type":"block","_key":"nls015","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nls016","text":"Bluetooth streaming: Stream phone calls, music, and audio directly from compatible smartphones and devices.","marks":[]}]},{"_type":"block","_key":"nls017","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nls018","text":"Rechargeable convenience: Reliable all-day battery performance with portable charging case included.","marks":[]}]},{"_type":"block","_key":"nls019","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nls020","text":"Compact and discreet fit: Small, comfortable design that fits naturally in the ear.","marks":[]}]},{"_type":"block","_key":"nls021","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nls022","text":"Advanced conversation support: RealTime Conversation Enhancement technology helps users follow multiple speakers more easily.","marks":[]}]},{"_type":"block","_key":"nls023","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nls024","text":"Portable charging case: Convenient on-the-go charging for busy lifestyles.","marks":[]}]},{"_type":"block","_key":"k33o","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k33n","text":"Signia Pure Charge&Go BCT IX","marks":[]}]},{"_type":"block","_key":"k33q","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k33p","text":"Signia Pure Charge&Go BCT IX is a stylish receiver-in-canal (RIC) hearing aid that makes it easy to stay connected. With built-in Bluetooth Classic, you can enjoy hands-free calls and audio streaming from your favorite devices, like smartphones, tablets, TVs, and computers.","marks":[]}]},{"_type":"block","_key":"k33s","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k33r","text":"Designed for active lifestyles, this hearing aid delivers powerful performance, all-day battery life, and clear conversations no matter where you are. It’s the perfect choice for anyone who wants reliable hearing support with modern, wireless convenience.","marks":[]}]},{"_type":"block","_key":"k33u","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k33t","text":"Unique features:","marks":[]}]},{"_type":"block","_key":"k33w","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k33v","text":"Universal Bluetooth Classic Connectivity: Easy pairing and reliable audio streaming.","marks":[]}]},{"_type":"block","_key":"k33y","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k33x","text":"Long battery usage: Up to 36 hours of battery life on a single charge","marks":[]}]},{"_type":"block","_key":"k340","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k33z","text":"Speech understanding in noisy environments: Powered by Integrated Xperience (IX) platform with RealTime Conversation Enhancement technology.","marks":[]}]},{"_type":"block","_key":"k342","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k341","text":"Discreet design: Sleek, discreet design that ranks among the smallest Bluetooth-compatible RIC devices available.","marks":[]}]},{"_type":"block","_key":"k344","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k343","text":"Built-in telecoil: For optimized performance in public venues.","marks":[]}]},{"_type":"block","_key":"k346","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k345","text":"Signia Styletto IX","marks":[]}]},{"_type":"block","_key":"k348","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k347","text":"The Styletto IX has a sleek design combined with high-performance technology. It offers cutting-edge features with a stylish and modern look, making it a popular choice for those who want functionality and aesthetics in one device.","marks":[]}]},{"_type":"block","_key":"k34a","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k349","text":"Key features of the Styletto IX include advanced speech clarity, even in noisy environments, thanks to its powerful sound processing technology. It also offers AI-powered personalization, which adapts the sound settings to the wearer’s preferences and specific listening situations.","marks":[]}]},{"_type":"block","_key":"k34c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k34b","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k34e","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k34d","text":"Rechargeable: It comes with a compact charging case that provides up to three days of use on a single charge.","marks":[]}]},{"_type":"block","_key":"k34g","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k34f","text":"Bluetooth connectivity: Enjoy seamless streaming of music, phone calls, and other audio directly from smartphones or other Bluetooth-enabled devices.","marks":[]}]},{"_type":"block","_key":"k34i","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k34h","text":"RealTime Conversation Enhancement technology: Adapts to the wearer’s conversational environment in real-time.","marks":[]}]},{"_type":"block","_key":"k34k","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k34j","text":"Signia Pure Charge&Go IX","marks":[]}]},{"_type":"block","_key":"k34m","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k34l","text":"The Pure Charge&Go IX offers a perfect balance of advanced technology and convenience. It is designed for a seamless hearing experience with the flexibility of rechargeability and premium sound quality.","marks":[]}]},{"_type":"block","_key":"k34o","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k34n","text":"Key features of the Pure Charge&Go IX include exceptional speech clarity, even in noisy environments, thanks to its advanced speech processing algorithms. It utilizes AI-based technology to personalize sound settings based on your unique listening environments, ensuring a natural and comfortable hearing experience.","marks":[]}]},{"_type":"block","_key":"k34q","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k34p","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k34s","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k34r","text":"Bluetooth connectivity: It supports direct streaming via Bluetooth, allowing you to connect effortlessly to smartphones, TVs, and other Bluetooth-enabled devices for music, phone calls, and more.","marks":[]}]},{"_type":"block","_key":"k34u","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k34t","text":"Rechargeable: It comes with a powerful lithium-ion battery that ensures long-lasting use with just a single charge.","marks":[]}]},{"_type":"block","_key":"k34w","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k34v","text":"Discreet and comfortable design: The Pure Charge&Go IX is suitable for all-day wear.","marks":[]}]},{"_type":"block","_key":"k34y","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k34x","text":"Signia Silk Charge&Go IX","marks":[]}]},{"_type":"block","_key":"k350","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k34z","text":"The Silk Charge&Go IX is part of Signia’s premium line of hearing aids, designed for users seeking a virtually invisible hearing solution that also offers the convenience of rechargeability. Known for its instant-fit design, the Silk Charge&Go IX provides high-quality hearing performance without the need for custom molds, making it an ideal option for those who value both discretion and ease of use.","marks":[]}]},{"_type":"block","_key":"k352","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k351","text":"UniqueFeatures:","marks":[]}]},{"_type":"block","_key":"k354","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k353","text":"Instant Fit Design: Unlike many in-the-ear hearing aids that require custom molds, the Silk Charge&Go IX offers an instant fit with soft silicone Click Sleeves, ensuring comfort and a secure fit right out of the box.","marks":[]}]},{"_type":"block","_key":"k356","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k355","text":"Crystal-Clear Sound: Equipped with advanced sound processing technology, this hearing aid delivers clear speech recognition and reduces background noise, even in challenging environments. This makes conversations in noisy settings much easier and more natural.","marks":[]}]},{"_type":"block","_key":"k358","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k357","text":"Bluetooth Streaming: The Silk Charge&Go IX supports direct Bluetooth streaming from smartphones and other Bluetooth-enabled devices, allowing users to listen to music, make phone calls, and watch TV with ease.","marks":[]}]},{"_type":"block","_key":"k35a","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k359","text":"Signia Insio IX IIC/CIC","marks":[]}]},{"_type":"block","_key":"k35c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k35b","text":"The Insio IX IIC/CIC is part of Signia’s lineup of custom-made hearing aids, designed to provide an ultra-discreet and comfortable hearing experience. Tailored specifically for the wearer, the IIC (Invisible-in-Canal) and CIC (Completely-in-Canal) models are nearly invisible when worn, making them an excellent choice for individuals who prioritize discretion without compromising on performance.","marks":[]}]},{"_type":"block","_key":"k35e","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k35d","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k35g","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k35f","text":"Custom Fit: Each Insio IX IIC/CIC hearing aid is custom-made to fit the wearer’s ear canal precisely, ensuring maximum comfort and a secure fit for extended wear.","marks":[]}]},{"_type":"block","_key":"k35i","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k35h","text":"Discreet Design: The IIC model is invisible within the ear canal, while the CIC is nearly invisible, offering a low-profile design ideal for those who prefer their hearing aids to be hidden.","marks":[]}]},{"_type":"block","_key":"k35k","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k35j","text":"Remote Control Capability: With Signia’s smartphone app, users can discreetly adjust their hearing aids, changing volume or sound settings with ease and without drawing attention.","marks":[]}]},{"_type":"block","_key":"k35m","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k35l","text":"Signia Pure Charge&Go T AX","marks":[]}]},{"_type":"block","_key":"k35o","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k35n","text":"Signia’s newest Augmented Focus™ technology, with updated eWindScreen and AX Soundscape Processing, helps to process speech and background noise separately to create a clear contrast in any environment. As a result, 94% of hearing aid users report excellent speech understanding while using Signia AX products.","marks":[]}]},{"_type":"block","_key":"k35q","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k35p","text":"Signia Pure Charge&Go T AX devices are appropriate for fitting mild to profound hearing losses. This product is available in the receiver-in-the-ear (RITE) style and offers a rechargeable battery. The portable rechargeability is a convenient option that provides 36 hours of listening on a single charge. The Signia Pure 312 AX offers the same benefits in sound processing as the Pure Charge&Go AX but with a disposable 312 battery solution in a sleek RITE design.","marks":[]}]},{"_type":"block","_key":"k35s","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k35r","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k35u","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k35t","text":"Bluetooth Connectivity: Allows for direct streaming for iOS and compatible Android smartphones. It handles the signal of a streaming input independently from other signals, ensuring the sound is even clearer and easier to optimize.","marks":[]}]},{"_type":"block","_key":"k35w","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k35v","text":"App: The Signia app integrates all the functionalities of the previous apps, including connectivity, remote control, the 24/7 Signia Assistant, and TeleCare into one unified app.","marks":[]}]},{"_type":"block","_key":"k35y","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k35x","text":"Remote help: The Signia app includes a 24/7 Signia Assistant and TeleCare. This integrates seamlessly into your fitting, making it easier for you to get instant support when needed and to stay in touch between visits.","marks":[]}]},{"_type":"block","_key":"k360","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k35z","text":"Signia Styletto AX","marks":[]}]},{"_type":"block","_key":"k362","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k361","text":"Signia’s Styletto AX offers many of the same features as the Pure AX solutions. The biggest difference in Styletto AX is its sleek lines and refined fit. This offers sophisticated styling and helps to avoid interference with wearing glasses.","marks":[]}]},{"_type":"block","_key":"k364","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k363","text":"Styletto AX is a slim RITE product that is appropriate for fitting mild to severe hearing losses. Styletto AX hearing aids are available in a rechargeable solution that can be charged on the go or at home for up to 20 hours of use per charge. The pocket-sized charging case’s wireless technology allows you to place the charger on a charging pad instead of having to plug it into a charging port.","marks":[]}]},{"_type":"block","_key":"k366","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k365","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k368","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k367","text":"Bluetooth Connectivity: Allows for direct streaming for iOS and compatible Android smartphones. It handles the signal of a streaming input independently from other signals, ensuring the sound is even clearer and easier to optimize.","marks":[]}]},{"_type":"block","_key":"k36a","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k369","text":"App: The Signia app integrates all the functionalities of the previous apps, including connectivity, remote control, the 24/7 Signia Assistant, and TeleCare into one unified app.","marks":[]}]},{"_type":"block","_key":"k36c","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k36b","text":"Remote help: The Signia app includes a 24/7 Signia Assistant and TeleCare. This integrates seamlessly into your fitting, making it easier for you to get instant support when needed and to stay in touch between visits.","marks":[]}]},{"_type":"block","_key":"k36e","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k36d","text":"Signia Insio Charge&Go AX","marks":[]}]},{"_type":"block","_key":"k36g","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k36f","text":"For many years custom in-the-ear (ITE) products only offered disposable battery solutions. Signia paved the way in the hearing aid industry by offering the world’s first custom hearing aids with contactless charging. The Insio Charge&Go AX devices are crafted specifically to your ear shape and provide a comfortable, discrete fit. In addition to the improved physical fit, there is also improved sound quality in the AX technology. In fact, a recent study found that 3 out of 4 hearing aid users experienced less listening effort with AX devices than with their previous hearing aids.","marks":[]}]},{"_type":"block","_key":"k36i","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k36h","text":"Signia Insio Charge&Go AX devices are appropriate for fitting mild to profound hearing losses. The devices are an ITE style and offer a rechargeable battery solution. Convenient charging is accessible on the go and provides 24 hours of listening on a single charge.","marks":[]}]},{"_type":"block","_key":"k36k","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k36j","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k36m","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k36l","text":"Bluetooth Connectivity: Allows for direct streaming for iOS and compatible Android smartphones. It handles the signal of a streaming input independently from other signals, ensuring the sound is even clearer and easier to optimize.","marks":[]}]},{"_type":"block","_key":"k36o","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k36n","text":"App: The Signia app integrates all the functionalities of the previous apps, including connectivity, remote control, the 24/7 Signia Assistant, and TeleCare into one unified app.","marks":[]}]},{"_type":"block","_key":"k36q","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k36p","text":"Remote help: The Signia app includes a 24/7 Signia Assistant and TeleCare. This integrates seamlessly into your fitting, making it easier for you to get instant support when needed and to stay in touch between visits.","marks":[]}]},{"_type":"block","_key":"k36s","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k36r","text":"Signia Motion X","marks":[]}]},{"_type":"block","_key":"k36w","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k36t","text":"The traditional behind-the-ear (BTE) style is currently available in Signia’s Xperience (X) platform. Motion X offers the world’s first rechargeable superpower BTE, offering up to an astounding 61 hours of wear-time on a single charge. A few other perks include its small size, sleek design, rechargeability, Bluetooth, and Signia Assistant","marks":[]},{"_type":"span","_key":"k36u","text":".","marks":["em"]},{"_type":"span","_key":"k36v","text":" With Bluetooth connectivity, rechargeability, and telecoil, Motion X opens the door to communication and confidence.","marks":[]}]},{"_type":"block","_key":"k36y","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k36x","text":"Signia Motion X devices are appropriate for fitting mild to profound hearing losses. The device is available in a BTE style and offers a rechargeable battery solution.","marks":[]}]},{"_type":"block","_key":"k370","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k36z","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k372","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k371","text":"Bluetooth: Motion X offers direct audio streaming from iOS (Apple) devices with the “made-for-iPhone (MFi) hearing aids” standard. Audio streaming from other mobile devices (Android smartphones, older Apple devices, PCs, laptops, and other Bluetooth mobile devices) is possible via the StreamLine Mic accessory.","marks":[]}]},{"_type":"block","_key":"k374","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k373","text":"App / Remote Help: Motion X connects to the Signia app, which contains the Signia Assistant and TeleCare support. By using artificial intelligence, the Signia Assistant offers immediate support whenever you need to adjust settings. Signia TeleCare enables you to keep in touch with your hearing care professional, so you get extra support on the spot.","marks":[]}]},{"_type":"block","_key":"k376","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k375","text":"Tinnitus: Motion X features a range of sound therapy options to help you cope with bothersome tinnitus.","marks":[]}]},{"_type":"block","_key":"k378","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k377","text":"Signia CROS AX","marks":[]}]},{"_type":"block","_key":"k37a","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k379","text":"Signia’s contralateral routing of the signal (CROS) AX and CROS X devices wirelessly transmit sound from your unaidable ear to the better-hearing ear, so that you can follow conversations effortlessly. This allows you to handle situations confidently when someone is speaking to you in your poorer hearing ear.","marks":[]}]},{"_type":"block","_key":"k37c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k37b","text":"The CROS AX is appropriate for individuals with single-sided hearing loss or single-sided deafness (SSD). There are several styles available in the Signia CROS, which allows you to decide which option fits your lifestyle and listening needs best. These options include:","marks":[]}]},{"_type":"block","_key":"k37e","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37d","text":"CROS Styletto AX: Portable charging with up to 20 hours of use with a single charge. A receiver-in-the-ear (RITE) with a sleek and streamlined design.","marks":[]}]},{"_type":"block","_key":"k37g","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37f","text":"CROS Pure Charge&Go AX: This RITE design offers convenient on-the-go rechargeability for up to 29 hours of wear time.","marks":[]}]},{"_type":"block","_key":"k37i","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37h","text":"CROS Pure 312: This RITE style uses a size 312 disposable battery and delivers up to 4 days of battery life.","marks":[]}]},{"_type":"block","_key":"k37k","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37j","text":"CROS Silk X: The only ready-to-wear completely-in-the-canal (CIC) delivers clearer speech understanding in an ultra-discreet size and instant fit.","marks":[]}]},{"_type":"block","_key":"k37m","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k37l","text":"**Available on the Signia X platform","marks":["em"]}]},{"_type":"block","_key":"k37o","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k37n","text":"Unique Features","marks":[]}]},{"_type":"block","_key":"k37q","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37p","text":"Bluetooth Connectivity: AX CROS/BiCROS solutions allow Bluetooth streaming for Apple® and Android phones for calls and music plus HandsFree calls with CallControl on select iOS phones.","marks":[]}]},{"_type":"block","_key":"k37s","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37r","text":"App: In the Signia app, users have access to hearing aids and CROS controls, streaming capabilities with multiple devices, care services via Signia TeleCare, and My WellBeing activity tracking.","marks":[]}]},{"_type":"block","_key":"k37u","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k37t","text":"Assistive Listening Devices & Technology by Signia","marks":[]}]},{"_type":"block","_key":"k37w","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37v","text":"StreamLine TV","marks":[]}]},{"_type":"block","_key":"k37y","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37x","text":"StreamLine Mic","marks":[]}]},{"_type":"block","_key":"k380","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37z","text":"StreamLine Remote","marks":[]}]},{"_type":"block","_key":"k382","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k381","text":"Older Signia Hearing Aid Models Supported By New Leaf Hearing Care In Colorado","marks":[]}]},{"_type":"block","_key":"k384","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k383","text":"These hearing aid models may still be supported for hearing aid servicing and repair by New Leaf Hearing Care in Arvada, CO and Littleton, CO. Please contact us for more information.","marks":[]}]},{"_type":"block","_key":"k386","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k385","text":"Signia Pure Charge&Go X","marks":[]}]},{"_type":"block","_key":"k388","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k387","text":"Signia Pure 312 X","marks":[]}]},{"_type":"block","_key":"k38a","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k389","text":"Signia CROS X","marks":[]}]},{"_type":"block","_key":"k38c","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38b","text":"Signia Intuis 3","marks":[]}]},{"_type":"block","_key":"k38e","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38d","text":"Signia Insio Nx","marks":[]}]},{"_type":"block","_key":"k38g","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38f","text":"Signia Pure Nx","marks":[]}]},{"_type":"block","_key":"k38i","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38h","text":"Signia Silk Nx","marks":[]}]},{"_type":"block","_key":"k38k","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38j","text":"Signia Silk Primax","marks":[]}]},{"_type":"block","_key":"k38m","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38l","text":"Signia Cellion Primax","marks":[]}]},{"_type":"block","_key":"k38o","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38n","text":"Signia Pure Primax","marks":[]}]},{"_type":"block","_key":"k38q","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k38p","text":"Frequently Asked Questions About Signia Hearing Aids","marks":[]}]},{"_type":"block","_key":"k38s","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k38r","text":"What is the top-of-the-line Signia hearing aid?","marks":[]}]},{"_type":"block","_key":"k38u","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k38t","text":"The Signia AX platform is the most current technology offered by Signia. This platform is available in the Styletto, Pure, and Insio Charge&Go hearing aid styles. The trademarked Augmented Focus (AX) technology is its top feature, which uses two pathways to process sound: one for speech and the other for background noise.","marks":[]}]},{"_type":"block","_key":"k38w","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k38v","text":"What are the levels of Signia Pure Charge&Go technology?","marks":[]}]},{"_type":"block","_key":"k38y","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k38x","text":"Signia offers the AX in five different technology levels, including: (1AX, 2AX, 3AX, 5AX, and 7AX) from least to most advanced technology, respectively.","marks":[]}]},{"_type":"block","_key":"k390","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k38z","text":"Can I adjust my Signia hearing aid?","marks":[]}]},{"_type":"block","_key":"k392","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k391","text":"Yes! Using the Signia app, you can change hearing aid programs and the volume level. There’s also an ability to adjust the sound balance between bass and treble.","marks":[]}]}]', updated_at=datetime('now') WHERE slug='signia-hearing-aids' AND content='[{"_type":"block","_key":"k33m","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k33l","text":"Signia Hearing Aids Available In Colorado","marks":[]}]},{"_type":"block","_key":"nls001","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"nls002","text":"Signia Active Mini IX","marks":[]}]},{"_type":"block","_key":"nls003","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nls004","text":"Signia Active Mini IX combines modern style with advanced hearing technology in a compact, earbud-inspired design. It is created for people who want hearing support that blends naturally into everyday life.","marks":[]}]},{"_type":"block","_key":"nls005","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nls006","text":"The Active Mini IX offers clear sound, wireless connectivity, and all-day comfort in a sleek and portable package.","marks":[]}]},{"_type":"block","_key":"nls007","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nls008","text":"It comes with a rechargeable design and Bluetooth streaming features that make it easy to enjoy calls, music, podcasts, and TV audio directly from compatible devices.","marks":[]}]},{"_type":"block","_key":"nls009","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nls010","text":"Signia Active Mini IX delivers a balance of style, convenience, and hearing performance in one discreet solution - perfect for active and social lifestyles.","marks":[]}]},{"_type":"block","_key":"nls011","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"nls012","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"nls013","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nls014","text":"Integrated Xperience (IX) platform: Enhances speech understanding and keeps conversations clear in noisy environments.","marks":[]}]},{"_type":"block","_key":"nls015","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nls016","text":"Bluetooth streaming: Stream phone calls, music, and audio directly from compatible smartphones and devices.","marks":[]}]},{"_type":"block","_key":"nls017","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nls018","text":"Rechargeable convenience: Reliable all-day battery performance with portable charging case included.","marks":[]}]},{"_type":"block","_key":"nls019","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nls020","text":"Compact and discreet fit: Small, comfortable design that fits naturally in the ear.","marks":[]}]},{"_type":"block","_key":"nls021","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nls022","text":"Advanced conversation support: RealTime Conversation Enhancement technology helps users follow multiple speakers more easily.","marks":[]}]},{"_type":"block","_key":"nls023","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"nls024","text":"Portable charging case: Convenient on-the-go charging for busy lifestyles.","marks":[]}]},{"_type":"block","_key":"k33o","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k33n","text":"Signia Pure Charge&Go BCT IX","marks":[]}]},{"_type":"block","_key":"k33q","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k33p","text":"Signia Pure Charge&Go BCT IX is a stylish receiver-in-canal (RIC) hearing aid that makes it easy to stay connected. With built-in Bluetooth Classic, you can enjoy hands-free calls and audio streaming from your favorite devices, like smartphones, tablets, TVs, and computers.","marks":[]}]},{"_type":"block","_key":"k33s","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k33r","text":"Designed for active lifestyles, this hearing aid delivers powerful performance, all-day battery life, and clear conversations no matter where you are. It’s the perfect choice for anyone who wants reliable hearing support with modern, wireless convenience.","marks":[]}]},{"_type":"block","_key":"k33u","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k33t","text":"Unique features:","marks":[]}]},{"_type":"block","_key":"k33w","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k33v","text":"Universal Bluetooth Classic Connectivity: Easy pairing and reliable audio streaming.","marks":[]}]},{"_type":"block","_key":"k33y","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k33x","text":"Long battery usage: Up to 36 hours of battery life on a single charge","marks":[]}]},{"_type":"block","_key":"k340","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k33z","text":"Speech understanding in noisy environments: Powered by Integrated Xperience (IX) platform with RealTime Conversation Enhancement technology.","marks":[]}]},{"_type":"block","_key":"k342","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k341","text":"Discreet design: Sleek, discreet design that ranks among the smallest Bluetooth-compatible RIC devices available.","marks":[]}]},{"_type":"block","_key":"k344","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k343","text":"Built-in telecoil: For optimized performance in public venues.","marks":[]}]},{"_type":"block","_key":"k346","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k345","text":"Signia Styletto IX","marks":[]}]},{"_type":"block","_key":"k348","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k347","text":"The Styletto IX has a sleek design combined with high-performance technology. It offers cutting-edge features with a stylish and modern look, making it a popular choice for those who want functionality and aesthetics in one device.","marks":[]}]},{"_type":"block","_key":"k34a","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k349","text":"Key features of the Styletto IX include advanced speech clarity, even in noisy environments, thanks to its powerful sound processing technology. It also offers AI-powered personalization, which adapts the sound settings to the wearer’s preferences and specific listening situations.","marks":[]}]},{"_type":"block","_key":"k34c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k34b","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k34e","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k34d","text":"Rechargeable: It comes with a compact charging case that provides up to three days of use on a single charge.","marks":[]}]},{"_type":"block","_key":"k34g","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k34f","text":"Bluetooth connectivity: Enjoy seamless streaming of music, phone calls, and other audio directly from smartphones or other Bluetooth-enabled devices.","marks":[]}]},{"_type":"block","_key":"k34i","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k34h","text":"RealTime Conversation Enhancement technology: Adapts to the wearer’s conversational environment in real-time.","marks":[]}]},{"_type":"block","_key":"k34k","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k34j","text":"Signia Pure Charge&Go IX","marks":[]}]},{"_type":"block","_key":"k34m","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k34l","text":"The Pure Charge&Go IX offers a perfect balance of advanced technology and convenience. It is designed for a seamless hearing experience with the flexibility of rechargeability and premium sound quality.","marks":[]}]},{"_type":"block","_key":"k34o","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k34n","text":"Key features of the Pure Charge&Go IX include exceptional speech clarity, even in noisy environments, thanks to its advanced speech processing algorithms. It utilizes AI-based technology to personalize sound settings based on your unique listening environments, ensuring a natural and comfortable hearing experience.","marks":[]}]},{"_type":"block","_key":"k34q","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k34p","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k34s","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k34r","text":"Bluetooth connectivity: It supports direct streaming via Bluetooth, allowing you to connect effortlessly to smartphones, TVs, and other Bluetooth-enabled devices for music, phone calls, and more.","marks":[]}]},{"_type":"block","_key":"k34u","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k34t","text":"Rechargeable: It comes with a powerful lithium-ion battery that ensures long-lasting use with just a single charge.","marks":[]}]},{"_type":"block","_key":"k34w","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k34v","text":"Discreet and comfortable design: The Pure Charge&Go IX is suitable for all-day wear.","marks":[]}]},{"_type":"block","_key":"k34y","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k34x","text":"Signia Silk Charge&Go IX","marks":[]}]},{"_type":"block","_key":"k350","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k34z","text":"The Silk Charge&Go IX is part of Signia’s premium line of hearing aids, designed for users seeking a virtually invisible hearing solution that also offers the convenience of rechargeability. Known for its instant-fit design, the Silk Charge&Go IX provides high-quality hearing performance without the need for custom molds, making it an ideal option for those who value both discretion and ease of use.","marks":[]}]},{"_type":"block","_key":"k352","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k351","text":"UniqueFeatures:","marks":[]}]},{"_type":"block","_key":"k354","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k353","text":"Instant Fit Design: Unlike many in-the-ear hearing aids that require custom molds, the Silk Charge&Go IX offers an instant fit with soft silicone Click Sleeves, ensuring comfort and a secure fit right out of the box.","marks":[]}]},{"_type":"block","_key":"k356","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k355","text":"Crystal-Clear Sound: Equipped with advanced sound processing technology, this hearing aid delivers clear speech recognition and reduces background noise, even in challenging environments. This makes conversations in noisy settings much easier and more natural.","marks":[]}]},{"_type":"block","_key":"k358","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k357","text":"Bluetooth Streaming: The Silk Charge&Go IX supports direct Bluetooth streaming from smartphones and other Bluetooth-enabled devices, allowing users to listen to music, make phone calls, and watch TV with ease.","marks":[]}]},{"_type":"block","_key":"k35a","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k359","text":"Signia Insio IX IIC/CIC","marks":[]}]},{"_type":"block","_key":"k35c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k35b","text":"The Insio IX IIC/CIC is part of Signia’s lineup of custom-made hearing aids, designed to provide an ultra-discreet and comfortable hearing experience. Tailored specifically for the wearer, the IIC (Invisible-in-Canal) and CIC (Completely-in-Canal) models are nearly invisible when worn, making them an excellent choice for individuals who prioritize discretion without compromising on performance.","marks":[]}]},{"_type":"block","_key":"k35e","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k35d","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k35g","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k35f","text":"Custom Fit: Each Insio IX IIC/CIC hearing aid is custom-made to fit the wearer’s ear canal precisely, ensuring maximum comfort and a secure fit for extended wear.","marks":[]}]},{"_type":"block","_key":"k35i","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k35h","text":"Discreet Design: The IIC model is invisible within the ear canal, while the CIC is nearly invisible, offering a low-profile design ideal for those who prefer their hearing aids to be hidden.","marks":[]}]},{"_type":"block","_key":"k35k","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k35j","text":"Remote Control Capability: With Signia’s smartphone app, users can discreetly adjust their hearing aids, changing volume or sound settings with ease and without drawing attention.","marks":[]}]},{"_type":"block","_key":"k35m","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k35l","text":"Signia Pure Charge&Go T AX","marks":[]}]},{"_type":"block","_key":"k35o","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k35n","text":"Signia’s newest Augmented Focus™ technology, with updated eWindScreen and AX Soundscape Processing, helps to process speech and background noise separately to create a clear contrast in any environment. As a result, 94% of hearing aid users report excellent speech understanding while using Signia AX products.","marks":[]}]},{"_type":"block","_key":"k35q","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k35p","text":"Signia Pure Charge&Go T AX devices are appropriate for fitting mild to profound hearing losses. This product is available in the receiver-in-the-ear (RITE) style and offers a rechargeable battery. The portable rechargeability is a convenient option that provides 36 hours of listening on a single charge. The Signia Pure 312 AX offers the same benefits in sound processing as the Pure Charge&Go AX but with a disposable 312 battery solution in a sleek RITE design.","marks":[]}]},{"_type":"block","_key":"k35s","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k35r","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k35u","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k35t","text":"Bluetooth Connectivity: Allows for direct streaming for iOS and compatible Android smartphones. It handles the signal of a streaming input independently from other signals, ensuring the sound is even clearer and easier to optimize.","marks":[]}]},{"_type":"block","_key":"k35w","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k35v","text":"App: The Signia app integrates all the functionalities of the previous apps, including connectivity, remote control, the 24/7 Signia Assistant, and TeleCare into one unified app.","marks":[]}]},{"_type":"block","_key":"k35y","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k35x","text":"Remote help: The Signia app includes a 24/7 Signia Assistant and TeleCare. This integrates seamlessly into your fitting, making it easier for you to get instant support when needed and to stay in touch between visits.","marks":[]}]},{"_type":"block","_key":"k360","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k35z","text":"Signia Styletto AX","marks":[]}]},{"_type":"block","_key":"k362","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k361","text":"Signia’s Styletto AX offers many of the same features as the Pure AX solutions. The biggest difference in Styletto AX is its sleek lines and refined fit. This offers sophisticated styling and helps to avoid interference with wearing glasses.","marks":[]}]},{"_type":"block","_key":"k364","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k363","text":"Styletto AX is a slim RITE product that is appropriate for fitting mild to severe hearing losses. Styletto AX hearing aids are available in a rechargeable solution that can be charged on the go or at home for up to 20 hours of use per charge. The pocket-sized charging case’s wireless technology allows you to place the charger on a charging pad instead of having to plug it into a charging port.","marks":[]}]},{"_type":"block","_key":"k366","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k365","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k368","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k367","text":"Bluetooth Connectivity: Allows for direct streaming for iOS and compatible Android smartphones. It handles the signal of a streaming input independently from other signals, ensuring the sound is even clearer and easier to optimize.","marks":[]}]},{"_type":"block","_key":"k36a","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k369","text":"App: The Signia app integrates all the functionalities of the previous apps, including connectivity, remote control, the 24/7 Signia Assistant, and TeleCare into one unified app.","marks":[]}]},{"_type":"block","_key":"k36c","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k36b","text":"Remote help: The Signia app includes a 24/7 Signia Assistant and TeleCare. This integrates seamlessly into your fitting, making it easier for you to get instant support when needed and to stay in touch between visits.","marks":[]}]},{"_type":"block","_key":"k36e","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k36d","text":"Signia Insio Charge&Go AX","marks":[]}]},{"_type":"block","_key":"k36g","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k36f","text":"For many years custom in-the-ear (ITE) products only offered disposable battery solutions. Signia paved the way in the hearing aid industry by offering the world’s first custom hearing aids with contactless charging. The Insio Charge&Go AX devices are crafted specifically to your ear shape and provide a comfortable, discrete fit. In addition to the improved physical fit, there is also improved sound quality in the AX technology. In fact, a recent study found that 3 out of 4 hearing aid users experienced less listening effort with AX devices than with their previous hearing aids.","marks":[]}]},{"_type":"block","_key":"k36i","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k36h","text":"Signia Insio Charge&Go AX devices are appropriate for fitting mild to profound hearing losses. The devices are an ITE style and offer a rechargeable battery solution. Convenient charging is accessible on the go and provides 24 hours of listening on a single charge.","marks":[]}]},{"_type":"block","_key":"k36k","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k36j","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k36m","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k36l","text":"Bluetooth Connectivity: Allows for direct streaming for iOS and compatible Android smartphones. It handles the signal of a streaming input independently from other signals, ensuring the sound is even clearer and easier to optimize.","marks":[]}]},{"_type":"block","_key":"k36o","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k36n","text":"App: The Signia app integrates all the functionalities of the previous apps, including connectivity, remote control, the 24/7 Signia Assistant, and TeleCare into one unified app.","marks":[]}]},{"_type":"block","_key":"k36q","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k36p","text":"Remote help: The Signia app includes a 24/7 Signia Assistant and TeleCare. This integrates seamlessly into your fitting, making it easier for you to get instant support when needed and to stay in touch between visits.","marks":[]}]},{"_type":"block","_key":"k36s","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k36r","text":"Signia Motion X","marks":[]}]},{"_type":"block","_key":"k36w","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k36t","text":"The traditional behind-the-ear (BTE) style is currently available in Signia’s Xperience (X) platform. Motion X offers the world’s first rechargeable superpower BTE, offering up to an astounding 61 hours of wear-time on a single charge. A few other perks include its small size, sleek design, rechargeability, Bluetooth, and Signia Assistant","marks":[]},{"_type":"span","_key":"k36u","text":".","marks":["em"]},{"_type":"span","_key":"k36v","text":" With Bluetooth connectivity, rechargeability, and telecoil, Motion X opens the door to communication and confidence.","marks":[]}]},{"_type":"block","_key":"k36y","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k36x","text":"Signia Motion X devices are appropriate for fitting mild to profound hearing losses. The device is available in a BTE style and offers a rechargeable battery solution.","marks":[]}]},{"_type":"block","_key":"k370","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k36z","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k372","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k371","text":"Bluetooth: Motion X offers direct audio streaming from iOS (Apple) devices with the “made-for-iPhone (MFi) hearing aids” standard. Audio streaming from other mobile devices (Android smartphones, older Apple devices, PCs, laptops, and other Bluetooth mobile devices) is possible via the StreamLine Mic accessory.","marks":[]}]},{"_type":"block","_key":"k374","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k373","text":"App / Remote Help: Motion X connects to the Signia app, which contains the Signia Assistant and TeleCare support. By using artificial intelligence, the Signia Assistant offers immediate support whenever you need to adjust settings. Signia TeleCare enables you to keep in touch with your hearing care professional, so you get extra support on the spot.","marks":[]}]},{"_type":"block","_key":"k376","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k375","text":"Tinnitus: Motion X features a range of sound therapy options to help you cope with bothersome tinnitus.","marks":[]}]},{"_type":"block","_key":"k378","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k377","text":"Signia CROS AX","marks":[]}]},{"_type":"block","_key":"k37a","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k379","text":"Signia’s contralateral routing of the signal (CROS) AX and CROS X devices wirelessly transmit sound from your unaidable ear to the better-hearing ear, so that you can follow conversations effortlessly. This allows you to handle situations confidently when someone is speaking to you in your poorer hearing ear.","marks":[]}]},{"_type":"block","_key":"k37c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k37b","text":"The CROS AX is appropriate for individuals with single-sided hearing loss or single-sided deafness (SSD). There are several styles available in the Signia CROS, which allows you to decide which option fits your lifestyle and listening needs best. These options include:","marks":[]}]},{"_type":"block","_key":"k37e","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37d","text":"CROS Styletto AX: Portable charging with up to 20 hours of use with a single charge. A receiver-in-the-ear (RITE) with a sleek and streamlined design.","marks":[]}]},{"_type":"block","_key":"k37g","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37f","text":"CROS Pure Charge&Go AX: This RITE design offers convenient on-the-go rechargeability for up to 29 hours of wear time.","marks":[]}]},{"_type":"block","_key":"k37i","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37h","text":"CROS Pure 312: This RITE style uses a size 312 disposable battery and delivers up to 4 days of battery life.","marks":[]}]},{"_type":"block","_key":"k37k","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37j","text":"CROS Silk X: The only ready-to-wear completely-in-the-canal (CIC) delivers clearer speech understanding in an ultra-discreet size and instant fit.","marks":[]}]},{"_type":"block","_key":"k37m","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k37l","text":"**Available on the Signia X platform","marks":["em"]}]},{"_type":"block","_key":"k37o","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k37n","text":"Unique Features","marks":[]}]},{"_type":"block","_key":"k37q","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37p","text":"Bluetooth Connectivity: AX CROS/BiCROS solutions allow Bluetooth streaming for Apple® and Android phones for calls and music plus HandsFree calls with CallControl on select iOS phones.","marks":[]}]},{"_type":"block","_key":"k37s","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37r","text":"App: In the Signia app, users have access to hearing aids and CROS controls, streaming capabilities with multiple devices, care services via Signia TeleCare, and My WellBeing activity tracking.","marks":[]}]},{"_type":"block","_key":"k37u","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k37t","text":"Assistive Listening Devices & Technology by Signia","marks":[]}]},{"_type":"block","_key":"k37w","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37v","text":"StreamLine TV","marks":[]}]},{"_type":"block","_key":"k37y","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37x","text":"StreamLine Mic","marks":[]}]},{"_type":"block","_key":"k380","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k37z","text":"StreamLine Remote","marks":[]}]},{"_type":"block","_key":"k382","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k381","text":"Older Signia Hearing Aid Models Supported By New Leaf Hearing Care In Colorado","marks":[]}]},{"_type":"block","_key":"k384","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k383","text":"These hearing aid models may still be supported for hearing aid servicing and repair by New Leaf Hearing Care in Arvada, CO and Littleton, CO. Please contact us for more information.","marks":[]}]},{"_type":"block","_key":"k386","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k385","text":"Signia Pure Charge&Go X","marks":[]}]},{"_type":"block","_key":"k388","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k387","text":"Signia Pure 312 X","marks":[]}]},{"_type":"block","_key":"k38a","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k389","text":"Signia CROS X","marks":[]}]},{"_type":"block","_key":"k38c","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38b","text":"Signia Intuis 3","marks":[]}]},{"_type":"block","_key":"k38e","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38d","text":"Signia Insio Nx","marks":[]}]},{"_type":"block","_key":"k38g","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38f","text":"Signia Pure Nx","marks":[]}]},{"_type":"block","_key":"k38i","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38h","text":"Signia Silk Nx","marks":[]}]},{"_type":"block","_key":"k38k","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38j","text":"Signia Silk Primax","marks":[]}]},{"_type":"block","_key":"k38m","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38l","text":"Signia Cellion Primax","marks":[]}]},{"_type":"block","_key":"k38o","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k38n","text":"Signia Pure Primax","marks":[]}]},{"_type":"block","_key":"k38q","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k38p","text":"Frequently Asked Questions About Signia Hearing Aids","marks":[]}]},{"_type":"block","_key":"k38s","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k38r","text":"What is the top-of-the-line Signia hearing aid?","marks":[]}]},{"_type":"block","_key":"k38u","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k38t","text":"The Signia AX platform is the most current technology offered by Signia. This platform is available in the Styletto, Pure, and Insio Charge&Go hearing aid styles. The trademarked Augmented Focus (AX) technology is its top feature, which uses two pathways to process sound: one for speech and the other for background noise.","marks":[]}]},{"_type":"block","_key":"k38w","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k38v","text":"What are the levels of Signia Pure Charge&Go technology?","marks":[]}]},{"_type":"block","_key":"k38y","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k38x","text":"Signia offers the AX in five different technology levels, including: (1AX, 2AX, 3AX, 5AX, and 7AX) from least to most advanced technology, respectively.","marks":[]}]},{"_type":"block","_key":"k390","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k38z","text":"Can I adjust my Signia hearing aid?","marks":[]}]},{"_type":"block","_key":"k392","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k391","text":"Yes! Using the Signia app, you can change hearing aid programs and the volume level. There’s also an ability to adjust the sound balance between bass and treble.","marks":[]}]}]';
